constexpr std::array<const char*,5> variables={"HG20C_ADC","LG20C_ADC","adopted_HGequivalent20C_ADC","saved_energy_MeV","LG_line_residual_ADC"};
constexpr std::array<const char*,7> conditions={"baseline","group_mean_MIP_same_hits","hit_min_0p3MeV","hit_min_1MeV","hit_min_3MeV","exclude_HG4000_hits","exclude_LG3000_hits"};
using Vec=std::vector<double>;
std::vector<std::string> split(const std::string&line){std::vector<std::string>v;std::istringstream in(line);std::string a;while(std::getline(in,a,'\t'))v.push_back(a);return v;}
double quantile(const Vec&sorted,double p){if(sorted.empty())return NAN;double f=p*(sorted.size()-1);size_t i=f;return sorted[i]+(f-i)*(sorted[std::min(i+1,sorted.size()-1)]-sorted[i]);}
struct Distribution {
 long long n=0;double mean=NAN,rms=NAN,q16=NAN,q50=NAN,q84=NAN,q95=NAN,q99=NAN,mode=NAN;
 Distribution()=default;
 Distribution(const Vec&v,double bin=1){n=v.size();if(!n)return;Stats s;Vec x=v;std::sort(x.begin(),x.end());for(double a:x)s.add(a);mean=s.mean;rms=s.rms();q16=quantile(x,.16);q50=quantile(x,.5);q84=quantile(x,.84);q95=quantile(x,.95);q99=quantile(x,.99);std::map<long long,long long>bins;for(double a:x)++bins[static_cast<long long>(std::floor(a/bin))];auto best=std::max_element(bins.begin(),bins.end(),[](auto&a,auto&b){return a.second<b.second;});mode=(best->first+.5)*bin;}
};
struct Fingerprint {uintmax_t bytes;fs::file_time_type time;bool operator==(const Fingerprint&o)const{return bytes==o.bytes&&time==o.time;}};
Fingerprint stamp(const fs::path&p){return {fs::file_size(p),fs::last_write_time(p)};}
struct Selected {int sample=0,file=0,run=0,time=0,trigger=0;Long64_t entry=0;bool window=false;double energy=0,hits=0;};
struct Channel {
 std::array<Vec,5> value;
 Stats rawH,rawL,tag0H,tag0L;
 long long events=0,hits=0,tag0=0,repeated=0,negative=0,zero=0,hg4000=0,hgAbove=0,lg3000=0,lgAbove=0,early=0,lgAdopted=0;
 double energy=0,capHenergy=0,capLenergy=0,x=NAN,y=NAN;
};
struct EventResult {
 int file=0,block=0,run=0,time=0,trigger=0;Long64_t entry=0;bool window=false;
 std::array<double,7>energy{};
 std::array<double,4>hits{};
 double adc=0,hgEnergy=0,lgEnergy=0,centralEnergy=0,centralHits=0,capH=0,capL=0,earlyEnergy=0,smallEnergy=0,smallHits=0,unique=0,negative=0,zero=0,tag0=0,repeated=0;
};
std::string sample(int s){return s?"mc":"data";}
std::string selection(int k){return k?"cog20_energy_window":"cog20";}
void normalized(TH1D&h){double n=h.Integral(0,h.GetNbinsX()+1);if(n)h.Scale(1/n);}
void overlay(TCanvas&c,int pad,TH1D&data,TH1D&mc,const std::string&title,bool log=false){c.cd(pad);if(log)gPad->SetLogy();data.SetTitle(title.c_str());data.SetLineColor(kGray+3);mc.SetLineColor(kRed-4);data.SetLineWidth(2);mc.SetLineWidth(2);normalized(data);normalized(mc);data.SetMaximum(1.2*std::max(data.GetMaximum(),mc.GetMaximum()));if(log)data.SetMinimum(1e-6);auto*d=data.DrawCopy("HIST"),*m=mc.DrawCopy("HIST SAME");TLegend legend(.52,.75,.89,.89);legend.AddEntry(d,"data, low-LG tail excluded","l");legend.AddEntry(m,"MC e_ssa / threshold","l");legend.SetBorderSize(0);legend.DrawClone();}
std::array<std::unique_ptr<TH1D>,2> histogram(const std::string&name,const std::array<Vec,2>&v,int n,double low,double high){std::array<std::unique_ptr<TH1D>,2>h;for(int s=0;s<2;++s){h[s]=std::make_unique<TH1D>((name+sample(s)).c_str(),"",n,low,high);h[s]->Sumw2();for(double x:v[s])h[s]->Fill(x);}return h;}
double resolution(const Vec&v){Distribution d(v);return d.mean>0?d.rms/d.mean:NAN;}
double gapImpact(const std::array<Vec,2>&v,const std::array<Vec,2>&baseline){double rd=resolution(v[0]),rm=resolution(v[1]),bd=resolution(baseline[0]),bm=resolution(baseline[1]);double gap=bd*bd-bm*bm;return gap!=0?1-(rd*rd-rm*rm)/gap:NAN;}
// File x 10 acquisition-block cluster bootstrap; resamples whole selected blocks.
std::pair<double,double> bootstrap(const std::array<std::vector<EventResult>,2>&events,int sel,int cond){
 std::array<std::map<std::pair<int,int>,std::vector<const EventResult*>>,2>groups;
 for(int s=0;s<2;++s)for(auto&e:events[s])if(!sel||e.window)groups[s][{e.file,e.block}].push_back(&e);
 std::array<std::vector<const std::vector<const EventResult*>*>,2>blocks;for(int s=0;s<2;++s)for(auto&[k,v]:groups[s])blocks[s].push_back(&v);
 if(blocks[0].size()<3||blocks[1].size()<3)return {NAN,NAN};std::mt19937 rng(9137+sel*71+cond*103);Vec impact;
 for(int b=0;b<300;++b){std::array<Vec,2>v,base;for(int s=0;s<2;++s){std::uniform_int_distribution<size_t>pick(0,blocks[s].size()-1);for(size_t k=0;k<blocks[s].size();++k)for(auto*e:*blocks[s][pick(rng)]){base[s].push_back(e->energy[0]);v[s].push_back(e->energy[cond]);}}double x=gapImpact(v,base);if(std::isfinite(x))impact.push_back(x);}
 std::sort(impact.begin(),impact.end());return {quantile(impact,.025),quantile(impact,.975)};
}
void writeDist(std::ostream&out,const Distribution&d){out<<d.n<<'\t'<<d.mean<<'\t'<<d.rms<<'\t'<<d.q16<<'\t'<<d.q50<<'\t'<<d.q84<<'\t'<<d.q95<<'\t'<<d.q99<<'\t'<<d.mode;}

void repaintRoot(const fs::path&dest,const std::string&energy){
 const fs::path rootPath=dest/"histograms.root";auto before=stamp(rootPath);auto file=openFile(rootPath.string());require(!file->TestBit(TFile::kRecovered),"Recovered histogram ROOT");
 const fs::path project=fs::canonical(fs::path(__FILE__)).parent_path().parent_path().parent_path();
 fs::path scratch=project/".scratch/raw_adc_repaint";fs::create_directories(scratch);std::string pattern=(scratch/"paint.XXXXXX").string();std::vector<char>tmp(pattern.begin(),pattern.end());tmp.push_back(0);char*made=mkdtemp(tmp.data());require(made,"Cannot allocate repaint scratch");fs::path work=made;
 TCanvas c("raw_review_repaint","",2250,1500);c.SetCanvasSize(2250,1500);c.Divide(2,2);
 auto save=[&](const std::string&name){c.SaveAs((work/name).c_str());require(fs::file_size(work/name)>0,"Empty repaint");fs::rename(work/name,dest/name);};
 const std::array<std::string,4>title={energy+", equal channel mixture, raw HG<2600;HG-ped, corrected to20C [ADC];Probability / bin",energy+", equal channel mixture, calibration-retained Tag1;LG-ped, corrected to20C [ADC];Probability / bin",energy+", equal channel mixture;Adopted HG-equivalent ADC at20C;Probability / bin",energy+", equal channel mixture;Saved hit energy [MeV];Probability / bin"};
 for(int v=0;v<4;++v)overlay(c,v+1,*object<TH1D>(*file,"data_common_"+std::string(variables[v])),*object<TH1D>(*file,"mc_common_"+std::string(variables[v])),title[v],true);
 save("common_channel_adc_energy.png");c.Clear();c.Divide(2,2);
 const std::array<std::string,4>names={"event_normalized_energy_","event_hits_","event_mean_hit_","event_energy_per_ADC_"};
 const std::array<std::string,4>titles={energy+", fixed selected cohort;Event energy / sample mean;Probability / bin","Recorded unmasked nonnegative hits;Event hit count;Probability / bin","E / recorded hits;Event mean hit energy [MeV];Probability / bin","Same hits, channel calibration mixture;Event energy / adopted ADC [MeV/ADC];Probability / bin"};
 for(int v=0;v<4;++v)overlay(c,v+1,*object<TH1D>(*file,names[v]+"data"),*object<TH1D>(*file,names[v]+"mc"),titles[v]);save("event_adc_hits.png");c.Clear();c.Divide(2,2);
 for(int v=0;v<4;++v){int s=v%2;c.cd(v+1);object<TH2D>(*file,sample(s)+(v<2?"_conditional_occupancy_map":"_HG4000_fraction_map"))->Draw("COLZ");}save("occupancy_hg4000_maps.png");c.Clear();
 require(before==stamp(rootPath),"Histogram ROOT changed while repainting");fs::remove_all(work);std::error_code error;fs::remove(scratch,error);
}

